net={(1,0):'Bat',(0,1):'Ball',(1,1):'Net',(1,2):'Stick',(1,3):'Goal',(2,3):'Field'}
# roll a cube: state maps face-direction -> normal vector; start with Net on bottom
def roll(o,d):
    # o: dict name->normal (x,y,z); rolling in +x/-x/+y/-y rotates normals
    dx,dy=d; r={}
    for k,(x,y,z) in o.items():
        if dx==1: r[k]=(-z,y,x)
        elif dx==-1: r[k]=(z,y,-x)
        elif dy==1: r[k]=(x,-z,y)
        else: r[k]=(x,z,-y)
    return r
